// simple_extension.go — a finite field over a subfield is generated by one point.

package finite_field

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/algebraic_element"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/nat_num/nat_arith"
	"github.com/euc-ai/xugo/library/proofs/nat_num/nat_order"
	"github.com/euc-ai/xugo/library/proofs/sets/cardinality"
	"github.com/euc-ai/xugo/library/proofs/sets/finite_set"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/registry"
)

// FiniteSubfieldSimple — a finite subfield l above a subfield k is k(z) for
// one point z of it, by a count. With q = card(k) and d = [l:k], l has q^d
// points. A point x that generates less has degree e = [k(x):k] with
// 0 < e < d, since k(x) has q^e points; every point of k(x) is fixed by the
// q^e-th power, which fixes at most q^e points; and these bounds for
// 0 < e < d add up to less than q^d.
var FiniteSubfieldSimple = finiteSubfieldSimpleThm{family.Add(registry.ProofEntry{
	Name: "FiniteSubfieldSimple",
	Key:  "prop_de81235fad68fd2e",
	Reading: "finite(l) is load-bearing; the count needs nothing of k beyond its being a subfield, " +
		"and at d = 1 every point of l generates, k(0) = k = l, the union of the count being empty. No " +
		"perfectness or separability enters: finite fields are read through their sizes alone.",
	Build: family.Sections(Statement{
		Binders: "∀M:field_on(A). ∀k l:set(A).",
		Hypotheses: []string{
			"subfield(M, k)",
			"subfield(M, l)",
			"k ⊆ l",
			"finite(l)",
		},
		Conclusion: "∃z:A. z ∈ l ∧ field_adjoin(M, k, {z}) = l",
		Abbrev: Abbrev{
			{Name: "below", Text: "λF:(num → set(A)). λn:num. {x:A | ∃e:num. 0 < e ∧ e < n ∧ x ∈ F(e)}"},
			{Name: "counted", Text: "«below»(λe:num. finite_constants(field_ring(M), card(k), e), " +
				"    extension_degree(M, k, l))"},
		},
	}, func(ctx *Script, headline string) *GoalStackNode {
		fewPoints := ctx.Lemma(Statement{
			Binders: "∀F:(num → set(A)). ∀q n:num.",
			Hypotheses: []string{
				"2 ≤ q",
				"∀e:num. 0 < e ⇒ finite(F(e)) ∧ card(F(e)) ≤ q ^ e",
			},
			Conclusion: "finite(«below»(F, n)) ∧ card(«below»(F, n)) < q ^ n",
		}, func(a *Argument, F *Arrow[Nat, Set[A]], q, n *Expr[Nat], large, bounded Fact) {
			nonzero := a.Have(
				"q is not zero",
				"q ≠ 0",
				ByArith(large))
			short := a.Have(
				"up to m = 1 no index lies strictly between zero and m, and q^m is positive",
				"∀m:num. m ≤ 1 ⇒ finite(«below»(F, m)) ∧ card(«below»(F, m)) < q ^ m",
				Derive(func(b *Argument) {
					m := b.FixAs[Nat]("m")
					small := b.Assume()
					noIndex := b.Have(
						"no index lies strictly between zero and m",
						"∀e:num. ¬(0 < e ∧ e < m)",
						b.ForEach(func(e *Expr[Nat]) Action { return ByArith(small) }))
					empty := b.Have(
						"so the set is empty",
						"«below»(F, m) = ∅",
						BySets(noIndex))
					b.Show(
						"the empty set has no points",
						empty.Rw(),
						By(
							Normalized,
							nonzero,
							finite_set.FiniteRules,
							cardinality.CardClauses,
							nat_order.PowPositive.At(q, m)))
				}))
			a.Induct(n)
			a.Base(
				"at zero the set is empty",
				By(short.At(a.TermAs[Nat]("0")), nat_order.ZeroLessEq.At(a.TermAs[Nat]("1"))))
			a.Step(
				"the index n adds at most q^n points, and q^n + q^n ≤ q^suc(n)",
				func(b *Argument, ih Fact) {
					b.Cases(b.Term("n = 0"))
					b.When(
						"at one the set is still empty",
						func(c *Argument, isZero Fact) {
							atMostOne := c.Have(
								"suc(n) is one",
								"suc(n) ≤ 1",
								ByArith(isZero))
							c.Show(
								"the empty set has no points",
								By(atMostOne, short.At(c.TermAs[Nat]("suc(n)"))))
						})
					b.Otherwise(
						"past the first index, the set at suc(n) adds F(n) to the set at n",
						func(c *Argument, notZero Fact) {
							positive := c.Have(
								"n is a positive index",
								"0 < n",
								ByArith(notZero))
							indexed := c.Have(
								"F(n) is finite with at most q^n points",
								"finite(F(n)) ∧ card(F(n)) ≤ q ^ n",
								By(positive, bounded.At(n)))
							before := c.TermAs[Set[A]]("«below»(F, n)")
							added := F.Apply(n)
							after := c.TermAs[Set[A]]("«below»(F, suc(n))")
							union := c.TermAs[Set[A]]("«below»(F, n) ∪ F(n)")
							cover := c.Have(
								"an index below suc(n) is n or below n",
								"«below»(F, suc(n)) ⊆ «below»(F, n) ∪ F(n)",
								BySets(nat_order.LessThanSucClause))
							finiteUnion := c.Have(
								"the union of two finite sets is finite",
								"finite(«below»(F, n) ∪ F(n))",
								By(ih, indexed, finite_set.FiniteUnionImp.At(before, added)))
							count := c.CalcOrder(
								nat_order.OrderCalc(c.Ctx()),
								c.TermAs[Nat]("card(«below»(F, suc(n)))"),
								LeLeg(
									c.TermAs[Nat]("card(«below»(F, n) ∪ F(n))"),
									"the set at suc(n) lies in the union",
									By(cover, finiteUnion, cardinality.CardSubset.At(after, union))),
								LeLeg(
									c.TermAs[Nat]("card(«below»(F, n)) + card(F(n))"),
									"a union has at most as many points as its two parts",
									By(ih, indexed, cardinality.CardUnionLe.At(before, added))))
							doubled := c.Have(
								"two copies of q^n are at most q copies, q being at least two",
								"2 * q ^ n ≤ q * q ^ n",
								By(large, nat_order.LessEqMulRightCancel.At(c.TermAs[Nat]("2"), q, c.TermAs[Nat]("q ^ n"))))
							c.Show(
								"so the set at suc(n) is finite, with fewer than q^suc(n) points",
								SplitConj(
									Case(
										"it lies in a finite union",
										By(cover, finiteUnion, finite_set.FiniteSubset.At(after, union))),
									Case(
										"and has fewer than q^n + q^n points, which is at most q^suc(n)",
										ByArith(count, ih, indexed, doubled, nat_arith.NatPow))))
						})
				})
		})

		properDegree := ctx.Lemma(Statement{
			Binders: "∀M:field_on(A). ∀k E l:set(A).",
			Hypotheses: []string{
				"subfield(M, k)",
				"subfield(M, E)",
				"subfield(M, l)",
				"k ⊆ E",
				"E ⊆ l",
				"E ≠ l",
				"finite(l)",
			},
			Conclusion: "0 < extension_degree(M, k, E) ∧ extension_degree(M, k, E) < extension_degree(M, k, l)",
		}, func(a *Argument, M field.FieldFact[on.M], k, E, l *Expr[Set[A]], h Fact) {
			given := a.Conjuncts(
				h,
				"k is a subfield",
				"E is a subfield",
				"l is a subfield",
				"k lies in E",
				"E lies in l",
				"E is not l",
				"l is finite")
			subK, subE, subL, kInE, eInL, proper, finiteL :=
				given[0], given[1], given[2], given[3], given[4], given[5], given[6]
			q := a.TermAs[Nat]("card(k)")
			e := a.TermAs[Nat]("extension_degree(M, k, E)")
			d := a.TermAs[Nat]("extension_degree(M, k, l)")
			zero := a.TermAs[Nat]("0")
			finiteE := a.Have(
				"E lies in l, so it is finite",
				"finite(E)",
				By(finiteL, eInL, finite_set.FiniteSubset.At(E, l)))
			large := a.Have(
				"k lies in the finite set E, and has at least two points",
				"2 ≤ card(k)",
				By(subK, finiteE, kInE, finite_set.FiniteSubset.At(k, E), FiniteSubfieldAtLeastTwo.Read(M).At(k)))
			sizeE := a.Have(
				"E has q^e points",
				"finite_extension(M, k, E) ∧ card(E) = card(k) ^ extension_degree(M, k, E)",
				By(subK, subE, kInE, finiteE, FiniteSubfieldSize.Read(M).At(k, E)))
			sizeL := a.Have(
				"l has q^d points",
				"finite_extension(M, k, l) ∧ card(l) = card(k) ^ extension_degree(M, k, l)",
				By(
					subK,
					subL,
					kInE,
					eInL,
					finiteL,
					set_order.SubsetTrans.At(k, E, l),
					FiniteSubfieldSize.Read(M).At(k, l)))
			smaller := a.Have(
				"E lies properly in l, so it has fewer points",
				"card(E) < card(l)",
				By(
					proper,
					eInL,
					finiteL,
					cardinality.CardSubsetLe.At(E, l),
					nat_order.NotLessEq.At(a.TermAs[Nat]("card(l)"), a.TermAs[Nat]("card(E)"))))
			bigger := a.Have(
				"E holds k, so it has more than one point",
				"1 < card(E)",
				ByArith(large, finiteE, kInE, cardinality.CardSubset.At(k, E)))
			nonzero := a.Have(
				"q is not zero",
				"card(k) ≠ 0",
				ByArith(large))
			a.Show(
				"so q^0 < q^e < q^d, and q is at least two",
				SplitConj(
					Case(
						"the exponent e is positive",
						By(Normalized, large, bigger, sizeE, nat_arith.NatPow, nat_order.LessThanPow.At(q, zero, e))),
					Case(
						"and below d",
						By(large, nonzero, smaller, sizeE, sizeL, nat_order.LessThanPow.At(q, e, d)))))
		})

		fixedByDegree := ctx.Lemma(Statement{
			Binders: "∀M:field_on(A). ∀k E:set(A). ∀x:A.",
			Hypotheses: []string{
				"subfield(M, k)",
				"subfield(M, E)",
				"k ⊆ E",
				"finite(E)",
				"x ∈ E",
			},
			Conclusion: "x ∈ finite_constants(field_ring(M), card(k), extension_degree(M, k, E))",
		}, func(a *Argument, M field.FieldFact[on.M], k, E *Expr[Set[A]], x *Expr[A], h Fact) {
			given := a.Conjuncts(
				h,
				"k is a subfield",
				"E is a subfield",
				"k lies in E",
				"E is finite",
				"x lies in E")
			subK, subE, kInE, finiteE, inE := given[0], given[1], given[2], given[3], given[4]
			fieldE := a.TermAs[FieldOps[A]]("restrict_field(M, E)")
			restricted := a.Have(
				"E is a finite field on its own carrier",
				"field_on(restrict_field(M, E)) ∧ finite(restrict_field(M, E).carrier)",
				By(subE, finiteE, field.SubfieldFieldOn.Read(M).At(E)))
			size := a.Have(
				"E has q^e points",
				"finite_extension(M, k, E) ∧ card(E) = card(k) ^ extension_degree(M, k, E)",
				By(subK, subE, kInE, finiteE, FiniteSubfieldSize.Read(M).At(k, E)))
			a.Show(
				"the size of a finite field is a power that fixes each of its points",
				Simp(Fwd(FiniteConstantsDef)),
				BySets(
					Normalized,
					restricted,
					inE,
					size,
					field.SubfieldSubset.Read(subE),
					FiniteFieldFixedByFrobenius.At(fieldE, x)))
		})

		return ctx.Theorem(headline, func(
			a *Argument,
			M field.FieldFact[on.M],
			k, l *Expr[Set[A]],
			h Fact,
		) {
			given := a.Conjuncts(
				h,
				"k is a subfield",
				"l is a subfield",
				"k lies in l",
				"l is finite")
			subK, subL, kInL, finiteL := given[0], given[1], given[2], given[3]
			noGenerator := a.SupposeNot()
			q := a.TermAs[Nat]("card(k)")
			d := a.TermAs[Nat]("extension_degree(M, k, l)")
			fixed := a.TermAs[Fun[Nat, Set[A]]]("λe:num. finite_constants(field_ring(M), card(k), e)")
			large := a.Have(
				"k lies in the finite set l, and has at least two points",
				"2 ≤ card(k)",
				By(subK, finiteL, kInL, finite_set.FiniteSubset.At(k, l), FiniteSubfieldAtLeastTwo.Read(M).At(k)))
			bounded := a.Have(
				"a positive power of q fixes at most that many points of M",
				Statement{
					Binders:    "∀e:num.",
					Hypotheses: []string{"0 < e"},
					Conclusion: "finite(finite_constants(field_ring(M), card(k), e)) ∧ " +
						"card(finite_constants(field_ring(M), card(k), e)) ≤ card(k) ^ e",
				},
				Derive(func(b *Argument) {
					e := b.FixAs[Nat]("e")
					positive := b.Assume()
					exceedsOne := b.Have(
						"q^e exceeds q^0, which is one",
						"1 < card(k) ^ e",
						By(
							Normalized,
							large,
							positive,
							nat_arith.NatPow,
							nat_order.LessThanPow.At(q, b.TermAs[Nat]("0"), e)))
					b.Show(
						"so the root bound applies",
						By(exceedsOne, FiniteConstantsBound.Read(M).At(q, e)))
				}))
			few := a.Have(
				"so the points fixed by the q^e-th power, for 0 < e < d, number fewer than q^d",
				"finite(«counted») ∧ card(«counted») < card(k) ^ extension_degree(M, k, l)",
				By(large, bounded, At(fewPoints, fixed, q, d)))
			size := a.Have(
				"l has q^d points",
				"finite_extension(M, k, l) ∧ card(l) = card(k) ^ extension_degree(M, k, l)",
				By(subK, subL, kInL, finiteL, FiniteSubfieldSize.Read(M).At(k, l)))
			cover := a.Have(
				"every point of l is among them: it generates a subfield "+
					"of degree e with 0 < e < d, whose q^e-th power fixes it",
				"l ⊆ «counted»",
				Derive(func(b *Argument) {
					b.Do(Simp(Fwd(set_basic.SubsetDef)))
					x := b.FixAs[A]("x")
					inL := b.Assume()
					E, generated := b.LetAs[Set[A]]("E", "field_adjoin(M, k, {x})")
					between := b.Have(
						"k(x) is a subfield between k and l, holding x",
						"subfield(M, E) ∧ k ⊆ E ∧ x ∈ E ∧ E ⊆ l",
						By(
							Normalized,
							generated,
							subK,
							subL,
							kInL,
							inL,
							algebraic_element.AdjoinElementBetween.Read(M).At(k, l, x)))
					proper := b.Have(
						"x does not generate, so k(x) is not l",
						"E ≠ l",
						By(generated, noGenerator, inL))
					degrees := b.Have(
						"so it has degree e with 0 < e < d",
						"0 < extension_degree(M, k, E) ∧ extension_degree(M, k, E) < extension_degree(M, k, l)",
						By(subK, subL, between, proper, finiteL, Read(properDegree, M).At(k, E, l)))
					fixedPoint := b.Have(
						"and it lies in the finite subfield k(x), so the q^e-th power fixes it",
						"x ∈ finite_constants(field_ring(M), card(k), extension_degree(M, k, E))",
						By(subK, between, finiteL, finite_set.FiniteSubset.At(E, l), Read(fixedByDegree, M).At(k, E, x)))
					b.Show(
						"so x is one of the points counted",
						BySets(degrees, fixedPoint))
				}))
			a.Show(
				"so l has fewer than q^d points, which it has",
				ByArith(few, size, cover, cardinality.CardSubset.At(l, a.TermAs[Set[A]]("«counted»"))))
		})
	}),
})}
